from dataclasses import dataclass, field
from mashumaro import DataClassDictMixin, field_options
from mashumaro.config import BaseConfig
@dataclass
class C(DataClassDictMixin):
 x: int = field(metadata=field_options(alias='xx'))
 class Config(BaseConfig):
  allow_deserialization_not_by_alias = True
  forbid_extra_keys = True
@dataclass
class P(DataClassDictMixin):
 c: C = field(metadata=field_options(flatten=True, flatten_rename={'x':'renamed'}))
print(P.from_dict({'renamed': 1}))
@dataclass
class D(DataClassDictMixin):
 x: int = 5
@dataclass
class Q(DataClassDictMixin):
 d: D = field(default_factory=lambda: D(9), metadata=field_options(flatten=True))
print(Q.from_dict({}))
